import { Component } from '@angular/core';
import {CommonModule} from "@angular/common";

@Component({
  selector: 'education',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './education.component.html',
  styleUrl: './education.component.css'
})
export class EducationComponent {
  sectionTitle = 'Education';

  educationList = [
    {
      degree: 'M.Sc. in Applied Statistics and Data Science',
      school: 'Jahangirnagar University',
      duration: '2024 - 2025 (Expected)',
      gpa: 'CGPA: 4.00 / 4.00'
    },
    {
      degree: 'B.Sc. in Statistics',
      school: 'Shahjalal University Science and Technology',
      duration: '2019 - 2023',
      gpa: 'CGPA: 3.46 / 4.00'
    },
    {
      degree: 'Higher Secondary School Certificate',
      school: 'BAF Shaheen College',
      duration: '2016 - 2018',
      gpa: 'GPA: 5.00 / 5.00'
    },
    {
      degree: 'Secondary School Certificate',
      school: 'BAF Shaheen College',
      duration: '2014 - 2016',
      gpa: 'GPA: 5.00 / 5.00'
    }
  ];
}
<section class="education-section">
  <section class="section-heading">
    <h3>{{ sectionTitle }}</h3>
  </section>

  <div class="education-list">
    <div class="education-card" *ngFor="let edu of educationList">
      <div class="edu-left">
        <div class="edu-icon" aria-hidden="true">
          <i class="fas fa-graduation-cap"></i>
        </div>
      </div>
      <div class="edu-right">
        <h4 class="degree">{{ edu.degree }}</h4>
        <p class="school">{{ edu.school }}</p>
        <div class="edu-footer">
          <span class="duration">{{ edu.duration }}</span>
          <span class="gpa" *ngIf="edu.gpa">{{ edu.gpa }}</span>
        </div>
      </div>
    </div>
  </div>
</section>
